10 *
11 * File:   dm_mem.sv
12 * Author: Florian Zaruba <zarubaf@iis.ee.ethz.ch>
13 * Date:   11.7.2018
14 *
15 * Description: Memory module for execution-based debug clients
16 *
17 */
18 
19 module dm_mem #(
20   parameter int unsigned        NrHarts          =  1,
21   parameter int unsigned        BusWidth         = 32,
22   parameter logic [NrHarts-1:0] SelectableHarts  = {NrHarts{1'b1}},
23   parameter int unsigned        DmBaseAddress    = '0
24 ) (
25   input  logic                             clk_i,       // Clock
26   input  logic                             rst_ni,      // debug module reset
27 
28   output logic [NrHarts-1:0]               debug_req_o,
29   input  logic [19:0]                      hartsel_i,
30   // from Ctrl and Status register
31   input  logic [NrHarts-1:0]               haltreq_i,
32   input  logic [NrHarts-1:0]               resumereq_i,
33   input  logic                             clear_resumeack_i,
34 
35   // state bits
36   output logic [NrHarts-1:0]               halted_o,    // hart acknowledge halt
37   output logic [NrHarts-1:0]               resuming_o,  // hart is resuming
38 
39   input  logic [dm::ProgBufSize-1:0][31:0] progbuf_i,    // program buffer to expose
40 
41   input  logic [dm::DataCount-1:0][31:0]   data_i,       // data in
42   output logic [dm::DataCount-1:0][31:0]   data_o,       // data out
43   output logic                             data_valid_o, // data out is valid
44   // abstract command interface
45   input  logic                             cmd_valid_i,
46   input  dm::command_t                     cmd_i,
47   output logic                             cmderror_valid_o,
48   output dm::cmderr_e                      cmderror_o,
49   output logic                             cmdbusy_o,
50   // data interface
51 
52   // SRAM interface
53   input  logic                             req_i,
54   input  logic                             we_i,
55   input  logic [BusWidth-1:0]              addr_i,
56   input  logic [BusWidth-1:0]              wdata_i,
57   input  logic [BusWidth/8-1:0]            be_i,
58   output logic [BusWidth-1:0]              rdata_o
59 );
60   localparam int unsigned DbgAddressBits = 12;
61   localparam int unsigned HartSelLen     = (NrHarts == 1) ? 1 : $clog2(NrHarts);
62   localparam int unsigned NrHartsAligned = 2**HartSelLen;
63   localparam int unsigned MaxAar         = (BusWidth == 64) ? 4 : 3;
64   localparam bit          HasSndScratch  = (DmBaseAddress != 0);
65   // Depending on whether we are at the zero page or not we either use `x0` or `x10/a0`
66   localparam logic [4:0]  LoadBaseAddr   = (DmBaseAddress == 0) ? 5'd0 : 5'd10;
67 
68   localparam logic [DbgAddressBits-1:0] DataBaseAddr        = (dm::DataAddr);
69   localparam logic [DbgAddressBits-1:0] DataEndAddr         = (dm::DataAddr + 4*dm::DataCount - 1);
70   localparam logic [DbgAddressBits-1:0] ProgBufBaseAddr     = (dm::DataAddr - 4*dm::ProgBufSize);
71   localparam logic [DbgAddressBits-1:0] ProgBufEndAddr      = (dm::DataAddr - 1);
72   localparam logic [DbgAddressBits-1:0] AbstractCmdBaseAddr = (ProgBufBaseAddr - 4*10);
73   localparam logic [DbgAddressBits-1:0] AbstractCmdEndAddr  = (ProgBufBaseAddr - 1);
74 
75   localparam logic [DbgAddressBits-1:0] WhereToAddr   = 'h300;
76   localparam logic [DbgAddressBits-1:0] FlagsBaseAddr = 'h400;
77   localparam logic [DbgAddressBits-1:0] FlagsEndAddr  = 'h7FF;
78 
79   localparam logic [DbgAddressBits-1:0] HaltedAddr    = 'h100;
80   localparam logic [DbgAddressBits-1:0] GoingAddr     = 'h104;
81   localparam logic [DbgAddressBits-1:0] ResumingAddr  = 'h108;
82   localparam logic [DbgAddressBits-1:0] ExceptionAddr = 'h10C;
83 
84   logic [dm::ProgBufSize/2-1:0][63:0]   progbuf;
85   logic [7:0][63:0]   abstract_cmd;
86   logic [NrHarts-1:0] halted_d, halted_q;
87   logic [NrHarts-1:0] resuming_d, resuming_q;
88   logic               resume, go, going;
89 
90   logic exception;
91   logic unsupported_command;
92 
93   logic [63:0] rom_rdata;
94   logic [63:0] rdata_d, rdata_q;
95   logic        word_enable32_q;
96 
97   // this is needed to avoid lint warnings related to array indexing
98   // resize hartsel to valid range
99   logic [HartSelLen-1:0] hartsel, wdata_hartsel;
100 
101   assign hartsel       = hartsel_i[HartSelLen-1:0];
102   assign wdata_hartsel = wdata_i[HartSelLen-1:0];
103 
104   logic [NrHartsAligned-1:0] resumereq_aligned, haltreq_aligned,
105                              halted_d_aligned, halted_q_aligned,
106                              halted_aligned, resumereq_wdata_aligned,
107                              resuming_d_aligned, resuming_q_aligned;
108 
109   assign resumereq_aligned       = NrHartsAligned'(resumereq_i);
110   assign haltreq_aligned         = NrHartsAligned'(haltreq_i);
111   assign resumereq_wdata_aligned = NrHartsAligned'(resumereq_i);
112 
113   assign halted_q_aligned        = NrHartsAligned'(halted_q);
114   assign halted_d                = NrHarts'(halted_d_aligned);
115   assign resuming_q_aligned      = NrHartsAligned'(resuming_q);
116   assign resuming_d              = NrHarts'(resuming_d_aligned);
117 
118   // distinguish whether we need to forward data from the ROM or the FSM
119   // latch the address for this
120   logic fwd_rom_d, fwd_rom_q;
121   dm::ac_ar_cmd_t ac_ar;
122 
123   // Abstract Command Access Register
124   assign ac_ar       = dm::ac_ar_cmd_t'(cmd_i.control);
125   assign debug_req_o = haltreq_i;
126   assign halted_o    = halted_q;
127   assign resuming_o  = resuming_q;
128 
129   // reshape progbuf
130   assign progbuf = progbuf_i;
131 
132   typedef enum logic [1:0] { Idle, Go, Resume, CmdExecuting } state_e;
133   state_e state_d, state_q;
134 
135   // hart ctrl queue
136   always_comb begin : p_hart_ctrl_queue
137     cmderror_valid_o = 1'b0;
138     cmderror_o       = dm::CmdErrNone;
139     state_d          = state_q;
140     go               = 1'b0;
141     resume           = 1'b0;
142     cmdbusy_o        = 1'b1;
143 
144     unique case (state_q)
145       Idle: begin
146         cmdbusy_o = 1'b0;
147         if (cmd_valid_i && halted_q_aligned[hartsel] && !unsupported_command) begin
148           // give the go signal
149           state_d = Go;
150         end else if (cmd_valid_i) begin
151           // hart must be halted for all requests
152           cmderror_valid_o = 1'b1;
153           cmderror_o = dm::CmdErrorHaltResume;
154         end
155         // CSRs want to resume, the request is ignored when the hart is
156         // requested to halt or it didn't clear the resuming_q bit before
157         if (resumereq_aligned[hartsel] && !resuming_q_aligned[hartsel] &&
158             !haltreq_aligned[hartsel] && halted_q_aligned[hartsel]) begin
159           state_d = Resume;
160         end
161       end
162 
163       Go: begin
164         // we are already busy here since we scheduled the execution of a program
165         cmdbusy_o = 1'b1;
166         go        = 1'b1;
167         // the thread is now executing the command, track its state
168         if (going) begin
169             state_d = CmdExecuting;
170         end
171       end
172 
173       Resume: begin
174         cmdbusy_o = 1'b1;
175         resume = 1'b1;
176         if (resuming_q_aligned[hartsel]) begin
177           state_d = Idle;
178         end
179       end
180 
181       CmdExecuting: begin
182         cmdbusy_o = 1'b1;
183         go        = 1'b0;
184         // wait until the hart has halted again
185         if (halted_aligned[hartsel]) begin
186           state_d = Idle;
187         end
188       end
189 
190       default: ;
191     endcase
192 
193     // only signal once that cmd is unsupported so that we can clear cmderr
194     // in subsequent writes to abstractcs
195     if (unsupported_command && cmd_valid_i) begin
196       cmderror_valid_o = 1'b1;
197       cmderror_o = dm::CmdErrNotSupported;
198     end
199 
200     if (exception) begin
201       cmderror_valid_o = 1'b1;
202       cmderror_o = dm::CmdErrorException;
203     end
204   end
205 
206   // word mux for 32bit and 64bit buses
207   logic [63:0] word_mux;
208   assign word_mux = (fwd_rom_q) ? rom_rdata : rdata_q;
209 
210   if (BusWidth == 64) begin : gen_word_mux64
211     assign rdata_o = word_mux;
212   end else begin : gen_word_mux32
213     assign rdata_o = (word_enable32_q) ? word_mux[32 +: 32] : word_mux[0 +: 32];
214   end
215 
216   // read/write logic
217   logic [63:0] data_bits;
218   logic [7:0][7:0] rdata;
219   always_comb begin : p_rw_logic
220 
221     halted_d_aligned   = NrHartsAligned'(halted_q);
222     resuming_d_aligned = NrHartsAligned'(resuming_q);
223     rdata_d        = rdata_q;
224     // convert the data in bits representation
225     data_bits      = data_i;
226     rdata          = '0;
227 
228     // write data in csr register
229     data_valid_o   = 1'b0;
230     exception      = 1'b0;
231     halted_aligned     = '0;
232     going          = 1'b0;
233 
234     // The resume ack signal is lowered when the resume request is deasserted
235     if (clear_resumeack_i) begin
236       resuming_d_aligned[hartsel] = 1'b0;
237     end
238     // we've got a new request
239     if (req_i) begin
240       // this is a write
241       if (we_i) begin
242         unique case (addr_i[DbgAddressBits-1:0]) inside
243           HaltedAddr: begin
244             halted_aligned[wdata_hartsel] = 1'b1;
245             halted_d_aligned[wdata_hartsel] = 1'b1;
246           end
247           GoingAddr: begin
248             going = 1'b1;
249           end
250           ResumingAddr: begin
251             // clear the halted flag as the hart resumed execution
252             halted_d_aligned[wdata_hartsel] = 1'b0;
253             // set the resuming flag which needs to be cleared by the debugger
254             resuming_d_aligned[wdata_hartsel] = 1'b1;
255           end
256           // an exception occurred during execution
257           ExceptionAddr: exception = 1'b1;
258           // core can write data registers
259           [DataBaseAddr:DataEndAddr]: begin
260             data_valid_o = 1'b1;
261             for (int i = 0; i < $bits(be_i); i++) begin
262               if (be_i[i]) begin
263                 data_bits[i*8+:8] = wdata_i[i*8+:8];
264               end
265             end
266           end
267           default ;
268         endcase
269 
270       // this is a read
271       end else begin
272         unique case (addr_i[DbgAddressBits-1:0]) inside
273           // variable ROM content
274           WhereToAddr: begin
275             // variable jump to abstract cmd, program_buffer or resume
276             if (resumereq_wdata_aligned[wdata_hartsel]) begin
277               rdata_d = {32'b0, dm::jal('0, 21'(dm::ResumeAddress[11:0])-21'(WhereToAddr))};
278             end
279 
280             // there is a command active so jump there
281             if (cmdbusy_o) begin
282               // transfer not set is shortcut to the program buffer if postexec is set
283               // keep this statement narrow to not catch invalid commands
284               if (cmd_i.cmdtype == dm::AccessRegister &&
285                   !ac_ar.transfer && ac_ar.postexec) begin
286                 rdata_d = {32'b0, dm::jal('0, 21'(ProgBufBaseAddr)-21'(WhereToAddr))};
287               // this is a legit abstract cmd -> execute it
288               end else begin
289                 rdata_d = {32'b0, dm::jal('0, 21'(AbstractCmdBaseAddr)-21'(WhereToAddr))};
290               end
291             end
292           end
293 
294           [DataBaseAddr:DataEndAddr]: begin
295             rdata_d = {
296                       data_i[$clog2(dm::ProgBufSize)'(addr_i[DbgAddressBits-1:3] -
297                           DataBaseAddr[DbgAddressBits-1:3] + 1'b1)],
298                       data_i[$clog2(dm::ProgBufSize)'(addr_i[DbgAddressBits-1:3] -
299                           DataBaseAddr[DbgAddressBits-1:3])]
300                       };
301           end
302 
303           [ProgBufBaseAddr:ProgBufEndAddr]: begin
304             rdata_d = progbuf[$clog2(dm::ProgBufSize)'(addr_i[DbgAddressBits-1:3] -
305                           ProgBufBaseAddr[DbgAddressBits-1:3])];
306           end
307 
308           // two slots for abstract command
309           [AbstractCmdBaseAddr:AbstractCmdEndAddr]: begin
310             // return the correct address index
311             rdata_d = abstract_cmd[3'(addr_i[DbgAddressBits-1:3] -
312                            AbstractCmdBaseAddr[DbgAddressBits-1:3])];
313           end
314           // harts are polling for flags here
315           [FlagsBaseAddr:FlagsEndAddr]: begin
316             // release the corresponding hart
317             if (({addr_i[DbgAddressBits-1:3], 3'b0} - FlagsBaseAddr[DbgAddressBits-1:0]) ==
318               (DbgAddressBits'(hartsel) & {{(DbgAddressBits-3){1'b1}}, 3'b0})) begin
319               rdata[DbgAddressBits'(hartsel) & DbgAddressBits'(3'b111)] = {6'b0, resume, go};
320             end
321             rdata_d = rdata;
322           end
323           default: ;
324         endcase
325       end
326     end
327 
328     data_o = data_bits;
329   end
330 
331   always_comb begin : p_abstract_cmd_rom
332     // this abstract command is currently unsupported
333     unsupported_command = 1'b0;
334     // default memory
335     // if ac_ar.transfer is not set then we can take a shortcut to the program buffer
336     abstract_cmd[0][31:0]  = dm::illegal();
337     // load debug module base address into a0, this is shared among all commands
338     abstract_cmd[0][63:32] = HasSndScratch ? dm::auipc(5'd10, '0) : dm::nop();
339     abstract_cmd[1][31:0]  = HasSndScratch ? dm::srli(5'd10, 5'd10, 6'd12) : dm::nop(); // clr lowest 12b -> DM base offset
340     abstract_cmd[1][63:32] = HasSndScratch ? dm::slli(5'd10, 5'd10, 6'd12) : dm::nop();
341     abstract_cmd[2][31:0]  = dm::nop();
342     abstract_cmd[2][63:32] = dm::nop();
343     abstract_cmd[3][31:0]  = dm::nop();
344     abstract_cmd[3][63:32] = dm::nop();
345     abstract_cmd[4][31:0]  = HasSndScratch ? dm::csrr(dm::CSR_DSCRATCH1, 5'd10) : dm::nop();
346     abstract_cmd[4][63:32] = dm::ebreak();
347     abstract_cmd[7:5]      = '0;
348 
349     // this depends on the command being executed
350     unique case (cmd_i.cmdtype)
351       // --------------------
352       // Access Register
353       // --------------------
354       dm::AccessRegister: begin
355         if (32'(ac_ar.aarsize) < MaxAar && ac_ar.transfer && ac_ar.write) begin
356           // store a0 in dscratch1
357           abstract_cmd[0][31:0] = HasSndScratch ? dm::csrr(dm::CSR_DSCRATCH1, 5'd10) : dm::nop();
358           // this range is reserved
359           if (ac_ar.regno[15:14] != '0) begin
360             abstract_cmd[0][31:0] = dm::ebreak(); // we leave asap
361             unsupported_command = 1'b1;
362           // A0 access needs to be handled separately, as we use A0 to load
363           // the DM address offset need to access DSCRATCH1 in this case
364           end else if (HasSndScratch && ac_ar.regno[12] && (!ac_ar.regno[5]) &&
365                       (ac_ar.regno[4:0] == 5'd10)) begin
366             // store s0 in dscratch
367             abstract_cmd[2][31:0]  = dm::csrw(dm::CSR_DSCRATCH0, 5'd8);
368             // load from data register
369             abstract_cmd[2][63:32] = dm::load(ac_ar.aarsize, 5'd8, LoadBaseAddr, dm::DataAddr);
370             // and store it in the corresponding CSR
371             abstract_cmd[3][31:0]  = dm::csrw(dm::CSR_DSCRATCH1, 5'd8);
372             // restore s0 again from dscratch
373             abstract_cmd[3][63:32] = dm::csrr(dm::CSR_DSCRATCH0, 5'd8);
374           // GPR/FPR access
375           end else if (ac_ar.regno[12]) begin
376             // determine whether we want to access the floating point register or not
377             if (ac_ar.regno[5]) begin
378               abstract_cmd[2][31:0] =
379                   dm::float_load(ac_ar.aarsize, ac_ar.regno[4:0], LoadBaseAddr, dm::DataAddr);
380             end else begin
381               abstract_cmd[2][31:0] =
382                   dm::load(ac_ar.aarsize, ac_ar.regno[4:0], LoadBaseAddr, dm::DataAddr);
383             end
384           // CSR access
385           end else begin
386             // data register to CSR
387             // store s0 in dscratch
388             abstract_cmd[2][31:0]  = dm::csrw(dm::CSR_DSCRATCH0, 5'd8);
389             // load from data register
390             abstract_cmd[2][63:32] = dm::load(ac_ar.aarsize, 5'd8, LoadBaseAddr, dm::DataAddr);
391             // and store it in the corresponding CSR
392             abstract_cmd[3][31:0]  = dm::csrw(dm::csr_reg_t'(ac_ar.regno[11:0]), 5'd8);
393             // restore s0 again from dscratch
394             abstract_cmd[3][63:32] = dm::csrr(dm::CSR_DSCRATCH0, 5'd8);
395           end
396         end else if (32'(ac_ar.aarsize) < MaxAar && ac_ar.transfer && !ac_ar.write) begin
397           // store a0 in dscratch1
398           abstract_cmd[0][31:0]  = HasSndScratch ? dm::csrr(dm::CSR_DSCRATCH1, LoadBaseAddr) : dm::nop();
399           // this range is reserved
400           if (ac_ar.regno[15:14] != '0) begin
401               abstract_cmd[0][31:0] = dm::ebreak(); // we leave asap
402               unsupported_command = 1'b1;
403           // A0 access needs to be handled separately, as we use A0 to load
404           // the DM address offset need to access DSCRATCH1 in this case
405           end else if (HasSndScratch && ac_ar.regno[12] && (!ac_ar.regno[5]) &&
406                       (ac_ar.regno[4:0] == 5'd10)) begin
407             // store s0 in dscratch
408             abstract_cmd[2][31:0]  = dm::csrw(dm::CSR_DSCRATCH0, 5'd8);
409             // read value from CSR into s0
410             abstract_cmd[2][63:32] = dm::csrr(dm::CSR_DSCRATCH1, 5'd8);
411             // and store s0 into data section
412             abstract_cmd[3][31:0]  = dm::store(ac_ar.aarsize, 5'd8, LoadBaseAddr, dm::DataAddr);
413             // restore s0 again from dscratch
414             abstract_cmd[3][63:32] = dm::csrr(dm::CSR_DSCRATCH0, 5'd8);
415           // GPR/FPR access
416           end else if (ac_ar.regno[12]) begin
417             // determine whether we want to access the floating point register or not
418             if (ac_ar.regno[5]) begin
419               abstract_cmd[2][31:0] =
420                   dm::float_store(ac_ar.aarsize, ac_ar.regno[4:0], LoadBaseAddr, dm::DataAddr);
421             end else begin
422               abstract_cmd[2][31:0] =
423                   dm::store(ac_ar.aarsize, ac_ar.regno[4:0], LoadBaseAddr, dm::DataAddr);
424             end
425           // CSR access
426           end else begin
427             // CSR register to data
428             // store s0 in dscratch
429             abstract_cmd[2][31:0]  = dm::csrw(dm::CSR_DSCRATCH0, 5'd8);
430             // read value from CSR into s0
431             abstract_cmd[2][63:32] = dm::csrr(dm::csr_reg_t'(ac_ar.regno[11:0]), 5'd8);
432             // and store s0 into data section
433             abstract_cmd[3][31:0]  = dm::store(ac_ar.aarsize, 5'd8, LoadBaseAddr, dm::DataAddr);
434             // restore s0 again from dscratch
435             abstract_cmd[3][63:32] = dm::csrr(dm::CSR_DSCRATCH0, 5'd8);
436           end
437         end else if (32'(ac_ar.aarsize) >= MaxAar || ac_ar.aarpostincrement == 1'b1) begin
438           // this should happend when e.g. ac_ar.aarsize >= MaxAar
439           // Openocd will try to do an access with aarsize=64 bits
440           // first before falling back to 32 bits.
441           abstract_cmd[0][31:0] = dm::ebreak(); // we leave asap
442           unsupported_command = 1'b1;
443         end
444 
445         // Check whether we need to execute the program buffer. When we
446         // get an unsupported command we really should abort instead of
447         // still trying to execute the program buffer, makes it easier
448         // for the debugger to recover
449         if (ac_ar.postexec && !unsupported_command) begin
450           // issue a nop, we will automatically run into the program buffer
451           abstract_cmd[4][63:32] = dm::nop();
452         end
453       end
454       // not supported at the moment
455       // dm::QuickAccess:;
456       // dm::AccessMemory:;
457       default: begin
458         abstract_cmd[0][31:0] = dm::ebreak();
459         unsupported_command = 1'b1;
460       end
461     endcase
462   end
463 
464   logic [63:0] rom_addr;
465   assign rom_addr = 64'(addr_i);
466 
467   // Depending on whether the debug module is located
468   // at the zero page we can instantiate a simplified version
469   // which only requires one scratch register per hart.
470   // For all other cases we need to set aside
471   // two registers per hart, hence we also need
472   // two scratch registers.
473   if (HasSndScratch) begin : gen_rom_snd_scratch
474     debug_rom i_debug_rom (
475       .clk_i,
476       .req_i,
477       .addr_i  ( rom_addr  ),
478       .rdata_o ( rom_rdata )
479     );
480   end else begin : gen_rom_one_scratch
481     // It uses the zero register (`x0`) as the base
482     // for its loads. The zero register does not need to
483     // be saved.
484     debug_rom_one_scratch i_debug_rom (
485       .clk_i,
486       .req_i,
487       .addr_i  ( rom_addr  ),
488       .rdata_o ( rom_rdata )
489     );
490   end
491 
492   // ROM starts at the HaltAddress of the core e.g.: it immediately jumps to
493   // the ROM base address
494   assign fwd_rom_d = logic'(addr_i[DbgAddressBits-1:0] >= dm::HaltAddress[DbgAddressBits-1:0]);
495 
496   always_ff @(posedge clk_i or negedge rst_ni) begin : p_regs
497     if (!rst_ni) begin
498       fwd_rom_q       <= 1'b0;
499       rdata_q         <= '0;
500       state_q         <= Idle;
501       word_enable32_q <= 1'b0;
502     end else begin
503       fwd_rom_q       <= fwd_rom_d;
504       rdata_q         <= rdata_d;
505       state_q         <= state_d;
506       word_enable32_q <= addr_i[2];
507     end
508   end
509 
510   always_ff @(posedge clk_i or negedge rst_ni) begin
511     if (!rst_ni) begin
512       halted_q   <= 1'b0;
513       resuming_q <= 1'b0;
514     end else begin
515       halted_q   <= SelectableHarts & halted_d;
516       resuming_q <= SelectableHarts & resuming_d;
517     end
518   end
519 
520 endmodule : dm_mem
</code>
